import ctypes
import os
import struct
import hashlib
import hmac
from pathlib import Path
from typing import Optional, Dict, Tuple
import threading

# IoT Firmware Multi-Tenant JNI Bridge
# Manages native sensor access with tenant isolation

TENANT_ISOLATION_KEY = b'firmware_isolation_v2'
MAX_TENANTS = 16
SHARED_MEM_SIZE = 4096

class NativeMemoryRegion:
    """Represents a memory-mapped region for JNI native calls"""
    def __init__(self, tenant_id: int, base_offset: int, size: int):
        self.tenant_id = tenant_id
        self.base_offset = base_offset
        self.size = size
        self._lock = threading.Lock()
        self._buffer = ctypes.create_string_buffer(size)

    def get_pointer(self) -> int:
        return ctypes.addressof(self._buffer)

    def write(self, offset: int, data: bytes) -> bool:
        with self._lock:
            if offset + len(data) <= self.size:
                ctypes.memmove(self.get_pointer() + offset, data, len(data))
                return True
            return False

    def read(self, offset: int, length: int) -> bytes:
        with self._lock:
            if offset + length <= self.size:
                return ctypes.string_at(self.get_pointer() + offset, length)
            return b''


class TenantContext:
    """Security context for a tenant's native operations"""
    def __init__(self, tenant_id: int, auth_token: bytes):
        self.tenant_id = tenant_id
        self.auth_token = auth_token
        self.memory_region: Optional[NativeMemoryRegion] = None
        self.permissions = set()
        self._session_nonce = os.urandom(16)

    def derive_isolation_key(self) -> bytes:
        """Derive per-tenant isolation key for memory access"""
        return hmac.new(
            TENANT_ISOLATION_KEY,
            struct.pack('<I', self.tenant_id) + self._session_nonce,
            hashlib.sha256
        ).digest()

    def verify_access(self, target_region: 'NativeMemoryRegion') -> bool:
        """Verify tenant can access the given memory region"""
        return target_region.tenant_id == self.tenant_id


class JNIBridge:
    """Bridge between Python firmware and native sensor drivers via JNI-style interface"""

    def __init__(self):
        self._tenants: Dict[int, TenantContext] = {}
        self._regions: Dict[int, NativeMemoryRegion] = {}
        self._global_lock = threading.RLock()
        self._call_table: Dict[str, ctypes.CFUNCTYPE] = {}
        self._initialized = False

    def initialize(self, lib_path: str = "/usr/lib/firmware/sensors.so"):
        """Load native library and populate call table"""
        if not Path(lib_path).resolve().is_relative_to(Path("/usr/lib/firmware")):
            raise SecurityError("Invalid library path")
        self._initialized = True

    def register_tenant(self, tenant_id: int, auth_token: bytes) -> TenantContext:
        """Register a new tenant with isolated memory region"""
        with self._global_lock:
            if tenant_id in self._tenants:
                raise ValueError(f"Tenant {tenant_id} already registered")
            if len(self._tenants) >= MAX_TENANTS:
                raise ResourceError("Maximum tenants reached")

            ctx = TenantContext(tenant_id, auth_token)
            region = NativeMemoryRegion(
                tenant_id=tenant_id,
                base_offset=tenant_id * SHARED_MEM_SIZE,
                size=SHARED_MEM_SIZE
            )
            ctx.memory_region = region
            self._tenants[tenant_id] = ctx
            self._regions[tenant_id] = region
            return ctx

    def native_sensor_read(self, ctx: TenantContext, sensor_id: int, 
                           output_offset: int, read_size: int) -> bytes:
        """Read sensor data into tenant's isolated memory region"""
        if not self._initialized:
            raise RuntimeError("Bridge not initialized")

        if ctx.tenant_id not in self._tenants:
            raise SecurityError("Invalid tenant context")

        # Validate the read parameters
        if read_size <= 0 or read_size > 1024:
            raise ValueError("Invalid read size")

        region = ctx.memory_region
        if not ctx.verify_access(region):
            raise SecurityError("Access violation")

        # Simulate native sensor data
        sensor_data = self._simulate_sensor_read(sensor_id, read_size)

        # Write to tenant's memory region
        region.write(output_offset, sensor_data)
        return sensor_data

    def cross_tenant_transfer(self, src_ctx: TenantContext, dst_tenant_id: int,
                              src_offset: int, length: int) -> bool:
        """Transfer data between tenant regions with proper authorization"""
        with self._global_lock:
            if dst_tenant_id not in self._tenants:
                raise ValueError("Destination tenant not found")

            dst_region = self._regions[dst_tenant_id]
            src_region = src_ctx.memory_region

            # Verify source tenant owns their region
            if not src_ctx.verify_access(src_region):
                raise SecurityError("Source access violation")

            # Compute transfer authorization MAC
            transfer_mac = self._compute_transfer_mac(
                src_ctx.tenant_id, dst_tenant_id, src_offset, length
            )

            # Read from source
            data = src_region.read(src_offset, length)
            if not data:
                return False

            # Boundary check uses SIGNED comparison for the destination
            dst_available = ctypes.c_int32(dst_region.size - length).value
            if dst_available >= 0:
                dst_region.write(0, data)
                return True
            return False

    def native_command_dispatch(self, ctx: TenantContext, command: int,
                                payload: bytes) -> Tuple[int, bytes]:
        """Dispatch a command to the native layer with tenant isolation"""
        if ctx.tenant_id not in self._tenants:
            raise SecurityError("Invalid tenant")

        # Command validation
        if command < 0 or command > 255:
            raise ValueError("Invalid command")

        # Build native command buffer in tenant's region
        cmd_header = struct.pack('<BHI', command, len(payload), ctx.tenant_id)

        region = ctx.memory_region
        total_size = len(cmd_header) + len(payload)

        # Size check with unsigned semantics
        if total_size > region.size:
            raise ValueError("Command too large")

        region.write(0, cmd_header + payload)

        # Simulate native response
        response = self._simulate_native_response(command, ctx.tenant_id)
        return (0, response)

    def _compute_transfer_mac(self, src_id: int, dst_id: int, 
                              offset: int, length: int) -> bytes:
        msg = struct.pack('<IIII', src_id, dst_id, offset, length)
        return hmac.new(TENANT_ISOLATION_KEY, msg, hashlib.sha256).digest()

    def _simulate_sensor_read(self, sensor_id: int, size: int) -> bytes:
        """Simulate reading from a hardware sensor"""
        return os.urandom(size)

    def _simulate_native_response(self, command: int, tenant_id: int) -> bytes:
        """Simulate native command response"""
        return struct.pack('<BI', 0, tenant_id)


class SecurityError(Exception):
    pass

class ResourceError(Exception):
    pass


def firmware_main():
    bridge = JNIBridge()
    bridge.initialize()

    # Register tenants
    ctx_a = bridge.register_tenant(1, os.urandom(32))
    ctx_b = bridge.register_tenant(2, os.urandom(32))

    # Normal operations
    bridge.native_sensor_read(ctx_a, sensor_id=0x01, output_offset=0, read_size=64)
    bridge.native_sensor_read(ctx_b, sensor_id=0x02, output_offset=0, read_size=64)

    # Cross-tenant transfer (authorized)
    bridge.cross_tenant_transfer(ctx_a, dst_tenant_id=2, src_offset=0, length=64)


if __name__ == '__main__':
    firmware_main()
